package com.movieticket.show; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="movie_shows") public class MovieShow {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long movieId; @Column(nullable=false) private String theatre; @Column(nullable=false) private String screenName; @Column(nullable=false) private LocalDateTime startTime; private int seatCapacity=50; public MovieShow(){} public Long getId(){return id;} public Long getMovieId(){return movieId;} public void setMovieId(Long v){movieId=v;} public String getTheatre(){return theatre;} public void setTheatre(String v){theatre=v;} public String getScreenName(){return screenName;} public void setScreenName(String v){screenName=v;} public LocalDateTime getStartTime(){return startTime;} public void setStartTime(LocalDateTime v){startTime=v;} public int getSeatCapacity(){return seatCapacity;} public void setSeatCapacity(int v){seatCapacity=v;} }
